<script setup>
import { computed,ref } from 'vue'
import { useRoute } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
defineProps({drafts:Boolean})
const store=useDemo(),route=useRoute()
const search=ref(''),status=ref(route.query.status||null),dateFrom=ref(''),dateTo=ref(''),error=ref(''),pending=ref(null)
const draftMode=computed(()=>route.path==='/reporter/drafts')
const rows=computed(()=>store.visibleEvents.value.filter(e=>(!draftMode.value||e.status==='draft')&&(!status.value||e.status===status.value)&&(!dateFrom.value||(e.date&&e.date>=dateFrom.value))&&(!dateTo.value||(e.date&&e.date<=dateTo.value))&&`${e.ref} ${e.type} ${e.place} ${e.vessels.map(v=>v.name).join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
const columns=[{name:'ref',label:'Report reference',field:'ref',align:'left',sortable:true},{name:'date',label:'Occurrence',field:e=>e.date||'Unknown',align:'left',sortable:true},{name:'type',label:'Event type',field:'type',align:'left',sortable:true},{name:'place',label:'Location',field:'place',align:'left'},{name:'vessels',label:'Vessels',field:e=>e.vessels.length,align:'left',sortable:true},{name:'status',label:'Status',field:'status',align:'left',sortable:true},{name:'actions',label:'',field:'id'}]
function discard(){try{store.remove('events',pending.value.id);pending.value=null}catch(e){error.value=e.message;pending.value=null}}
</script>
<template><div class="page-wrap"><PageHeader :title="draftMode?'Saved drafts':'My reports'" :subtitle="draftMode?'Continue an unfinished report or discard it.':'Search your account’s reports and follow their review status.'"><template #actions><q-btn flat color="primary" no-caps :label="draftMode?'All my reports':'Saved drafts'" :to="draftMode?'/reporter/reports':'/reporter/drafts'"/><q-btn flat color="primary" no-caps label="Evidence and documents" to="/reporter/documents"/><q-btn color="primary" icon="add" no-caps label="New spot report" to="/reporter/reports/new"/></template></PageHeader><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md">{{error}}</q-banner><section class="panel"><div class="toolbar-row"><q-input v-model="search" outlined dense clearable label="Search reference, vessel or place" @clear="search=''"/><q-select v-if="!draftMode" v-model="status" outlined dense clearable label="Status" :options="['draft','submitted','under_review','correction_requested','resubmitted','validated']"/><q-input v-model="dateFrom" type="date" outlined dense label="From date" stack-label/><q-input v-model="dateTo" type="date" outlined dense label="To date" stack-label/></div><q-table :rows="rows" :columns="columns" row-key="id" flat :pagination="{rowsPerPage:10,sortBy:'date',descending:true}" :rows-per-page-options="[10,25,50]" wrap-cells><template #body-cell-ref="p"><q-td :props="p"><router-link class="record-link" :to="`/reporter/reports/${p.row.id}`">{{p.row.ref||'Draft report'}}</router-link></q-td></template><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="p.row.status"/></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn flat color="primary" no-caps :label="p.row.status==='draft'?'Continue':'Open'" :to="`/reporter/reports/${p.row.id}${p.row.status==='draft'?'/edit':''}`"/><q-btn v-if="p.row.status==='draft'" flat round icon="delete_outline" color="negative" aria-label="Discard draft" @click="pending=p.row"/></q-td></template><template #no-data><div class="empty-state full-width"><q-icon name="find_in_page" size="40px"/><p>{{search||status||dateFrom||dateTo?'No reports match these filters.':'No reports yet. Start a spot report to save your first draft.'}}</p></div></template></q-table></section><q-dialog :model-value="!!pending" @update:model-value="pending=null"><q-card style="max-width:420px"><q-card-section class="text-h6">Discard this draft?</q-card-section><q-card-section>{{pending?.ref}} will be removed from this demo. Submitted reports are retained.</q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Keep draft" v-close-popup/><q-btn color="negative" no-caps label="Discard draft" @click="discard"/></q-card-actions></q-card></q-dialog></div></template>
